def fib(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b
print(list(fib(5)))

def numbers(n):
    for i in range(n):
        yield i
print(list(numbers(0)))

def f():
    yield [1, 2]
print(list(f()))

